#include "DTC.h"
#include <algorithm>
#include <cctype>
namespace injector_diagnostic {namespace {std::string normalize(std::string code){std::transform(code.begin(),code.end(),code.begin(),[](unsigned char c){return static_cast<char>(std::toupper(c));});return code;}} DtcDatabase::DtcDatabase(){entries_.emplace("P0100",DtcInfo{"P0100","Mass Air Flow sensor circuit malfunction","Air intake",{"MAF sensor or connector issue","Wiring/open circuit","Power or ground problem"},{"Inspect connector and wiring","Check MAF power/ground","Compare MAF signal with live data"}});entries_.emplace("P0115",DtcInfo{"P0115","Engine coolant temperature sensor circuit malfunction","Engine temperature",{"ECT sensor fault","Connector/wiring fault","Reference or ground issue"},{"Inspect ECT connector","Check wiring continuity","Compare temperature reading with engine condition"}});entries_.emplace("P0120",DtcInfo{"P0120","Throttle position sensor circuit malfunction","Throttle control",{"TPS signal fault","Wiring/connector issue","Reference voltage problem"},{"Inspect TPS connector","Check reference voltage and ground","Compare TPS signal through its range"}});} std::optional<DtcInfo>DtcDatabase::find(const std::string& code)const{auto it=entries_.find(normalize(code));if(it==entries_.end())return std::nullopt;return it->second;} std::vector<DtcInfo>DtcDatabase::all()const{std::vector<DtcInfo> result;result.reserve(entries_.size());for(const auto& [_,info]:entries_)result.push_back(info);return result;} }
